package com.bookstore.controller; import com.bookstore.entity.Book; import com.bookstore.service.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; @Controller @RequestMapping("/books") public class BookController{private final BookService service;private final AuthorService authors;private final CategoryService categories;public BookController(BookService s,AuthorService a,CategoryService c){service=s;authors=a;categories=c;}@GetMapping String list(@RequestParam(required=false)String q,Model m){m.addAttribute("books",service.search(q));m.addAttribute("q",q);return "books/list";}@GetMapping("/new")String create(Model m){form(m,new Book());return "books/form";}@GetMapping("/edit/{id}")String edit(@PathVariable Long id,Model m){form(m,service.findById(id));return "books/form";}@PostMapping("/save")String save(@Valid @ModelAttribute Book book,BindingResult r,@RequestParam Long authorId,@RequestParam Long categoryId,Model m){if(r.hasErrors()){form(m,book);return "books/form";}service.save(book,authorId,categoryId);return "redirect:/books";}@GetMapping("/delete/{id}")String delete(@PathVariable Long id){service.delete(id);return "redirect:/books";}private void form(Model m,Book b){m.addAttribute("book",b);m.addAttribute("authors",authors.findAll());m.addAttribute("categories",categories.findAll());}}